          "hanc prīmum tūtāre domum. cui parvus Iūlus,",
          "cui pater et coniūnx quondam tua dicta relinquor?'",
          "Tālia vōciferāns gemitū tēctum omne replēbat,",
          "cum subitum dictūque oritur mīrābile mōnstrum.",
