          "ecce levis summō dē vertice vīsūs Iūlī",
          "fundere lūmen apex, tāctūque innoxia mollīs",
          "lambere flammā comās et circum tempora pāscī.",
          "nōs pavidī trepidāre metū crīnemque flagrantem",
