          "Vix ea fātus erat senior, subitōque fragōre",
          "intonuit laevum, et dē caelō lāpsa per umbrās",
          "stēlla facem dūcēns multa cum lūce cucurrit.",
          "illam summa super lābentem culmina tēctī",
