          "dat lūcem et lātē circum loca sulphure fūmant.",
          "hic vērō victus genitor sē tollit ad aurās",
          "adfāturque deōs et sānctum sīdus adōrat.",
          "'iam iam nūlla mora est; sequor et quā dūcitis adsum,"
