          "prīma tulit tellūs, eadem vōs ūbere laetō",
          "accipiet reducēs. antīquam exquīrite mātrem.",
          "hīc domus Aenēae cūnctīs dominābitur ōrīs",
          "et nātī nātōrum et quī nāscentur ab illīs.'",
          "haec Phoebus; mixtōque ingēns exortā tumultū",
          "laetitiā, et cūnctī quae sint ea moenia quaerunt,"
