          "Pergamaque Īliacamque iūgis hanc addidit arcem.",
          "sed tibi quī cursum ventī, quae fāta dedēre?",
          "aut quisnam ignārum nostrīs deus appulit ōrīs?",
          "quid puer Ascanius? superatne et vēscitur aura?",
          "quem tibi iam Troiā—",
          "ecquā tamen puerō est āmissae cūra parentis?",
          "ecquid in antīquam virtūtem animōsque virīlīs",
