          "noctem illam tēctī silvīs immānia mōnstra",
          "perferimus, nec quae sonitum det causā vidēmus.",
          "nam neque erant astrōrum ignēs nec lūcidus aethra",
          "sīderea polus, obscūrō sed nūbila caelō,",
