        "id": "liber-iv-701-705",
        "latinTitle": "Versūs 701–705",
        "title": "Verses 701–705",
        "paragraphs": [
          "mīlle trahēns variōs adversō sōle colōrēs",
          "dēvolat et suprā caput astitit. 'hunc ego Dītī",
          "sacrum iussa ferō tēque istō corpore solvō':",
          "sīc ait et dextra crīnem secat, omnis et ūna",
          "dīlāpsus calor atque in ventōs vīta recessit."
        ],
