          "ferre suī dederat monimentum et pignus amōris.'",
          "sīc fātus cingit viridantī tempora laurō",
          "et prīmum ante omnis victōrem appellat Acestēn.",
          "nec bonus Eurytiōn praelātō invīdit honōrī,",
