          "Hectoris hic magnī fuerat comes, Hectora circum",
          "et lituō pugnās īnsignīs obībat et hastā.",
          "postquam illum vītā victor spoliāvit Achillēs,",
          "Dardaniō Aenēae sēsē fortissimus hērōs",
