          "et summās carpēns media inter cornua saetās",
          "ignibus impōnit sacrīs, lībāmina prīma,",
          "vōce vocāns Hecatēn caelōque Erebōque potentem.",
          "suppōnunt aliī cultrōs tepidumque cruōrem",
