          "septemque ūna sibi mūrō circumdabit arcēs,",
          "fēlīx prōle virum: quālīs Berecyntia māter",
          "invehitur currū Phrygiās turrīta per urbēs",
          "laetā deum partū, centum complexā nepōtēs,",
          "omnīs caelicolās, omnīs supera alta tenentīs.",
