          "Fāma volat parvam subitō vulgāta per urbem",
          "ōcius īre equitēs Tyrrhēnī ad līmina rēgis.",
          "vōta metū duplicant mātrēs, propiusque perīclō",
          "it timor et maior Mārtis iam appāret imāgō.",
          "tum pater Evandrus dextram complexūs euntis",
          "haeret inexplētus lacrimāns ac tālia fātur:",
          "'ō mihi praeteritōs referat sī Iuppiter annōs,",
          "quālis eram cum prīmam aciem Praeneste sub ipsā",
          "strāvī scūtōrumque incendī victor acervōs",
