          "tōtus conlūcēns veste atque īnsignibus albīs.",
          "quem congressus agit campō, lāpsumque superstāns",
          "immolat ingentīque umbrā tegit, arma Serestus",
          "lēcta refert umerīs tibi, rēx Grādīve, tropaeum.",
