          "Dardanidēs contrā furit: Ānxuris ēnse sinistram",
          "et tōtum clipeī ferrō dēiēcerat orbem",
          "(dīxerat ille aliquid magnum vimque adfore verbō",
          "crēdiderat, caelōque animum fortasse ferēbat",
