          "ipsa immōta manēns) prōlem Dolichāonis Hebrum",
          "sternit humī, cum quō Latagum Palmumque fugācem,",
          "sed Latagum saxō atque ingentī fragmine montis",
          "occupat os faciemque adversam, poplite Palmum"
