          "nōn haec Evandrō dē tē prōmissā parentī",
          "discēdēns dederam, cum mē complexūs euntem",
          "mitteret in magnum imperium metuēnsque monēret",
          "ācrīs esse virōs, cum dūra proelia gente.",
          "et nunc ille quidem spē multum captus inānī",
          "fors et vōta facit cumulatque altāria dōnīs,",
          "nōs iuvenem exanimum et nīl iam caelestibus ūllīs",
          "dēbentem vānō maestī comitāmur honōre.",
          "īnfēlīx, nātī fūnus crūdēle vidēbis!",
          "hī nostrī reditūs exspectātīque triumphī?",
          "haec mea magna fidēs? at nōn, Evandre, pudendīs",
          "vulneribus pulsum aspiciēs, nec sospite dīrum",
          "optābis nātō fūnus pater. eī mihi quantum",
          "praesidium, Ausonia, et quantum tū perdis, Iūle!'",
          "Haec ubi dēflēvit, tollī miserābile corpus",
          "imperat, et tōtō lēctōs ex agmine mittit",
          "mīlle virōs quī suprēmum comitentur honōrem",
          "intersintque patris lacrimīs, sōlācia lūctūs",
          "exigua ingentīs, miserō sed dēbita patrī.",
          "haud sēgnēs aliī crātis et molle feretrum",
          "arbuteīs texunt virgīs et vīmine quernō",
          "exstrūctōsque torōs obtentū frondis inumbrant.",
          "hic iuvenem agrestī sublīmem strāmine pōnunt:",
          "quālem virgineō dēmessum pollice flōrem",
          "seu mollis violae seu languentis hyacinthī,",
          "cui neque fulgor adhūc nec dum suā fōrmā recessit,",
          "nōn iam māter alit tellūs virīsque ministrat.",
          "tum geminās vestīs aurōque ostrōque rigentīs",
          "extulit Aenēās, quās illī laeta labōrum",
          "ipsa suīs quondam manibus Sīdoniā Dīdō",
          "fēcerat et tenuī tēlās discrēverat aurō.",
          "hārum ūnam iuvenī suprēmum maestus honōrem",
          "induit ārsūrāsque comās obnūbit amictū,",
          "multaque praetereā Laurentīs praemia pugnae",
          "aggerat et longō praedam iubet ōrdine dūcī;",
          "addit equōs et tēla quibus spoliāverat hostem.",
          "vīnxerat et post terga manūs, quōs mitteret umbrīs",
          "īnferiās, caesō sparsūrus sanguine flammās,",
          "indūtōsque iubet truncōs hostīlibus armīs",
          "ipsōs ferre ducēs inimīcaque nōmina fīgī.",
          "dūcitur īnfēlīx aevō cōnfectus Acoetēs,",
          "pectora nunc foedāns pugnīs, nunc unguibus ōra,",
          "sternitur et tōtō prōiectus corpore terrae;",
          "dūcunt et Rutulō perfūsōs sanguine currūs.",
          "post bellātor equus positīs īnsignibus Aethōn",
          "it lacrimāns guttīsque ūmectat grandibus ōra.",
          "hastam aliī galeamque ferunt, nam cētera Turnus",
          "victor habet. tum maesta phalānx Teucrīque sequuntur",
          "Tyrrhēnīque omnēs et versīs Arcadēs armīs.",
          "postquam omnīs longē comitum praecesserat ōrdō,",
          "substitit Aenēās gemitūque haec addidit altō:",
          "'nōs aliās hinc ad lacrimās eadem horrida bellī",
          "fāta vocant: salvē aeternum mihi, maxime Palla,",
          "aeternumque valē.' nec plūra effātus ad altōs",
          "tendēbat mūrōs gressumque in castra ferēbat.",
          "Iamque ōrātōrēs aderant ex urbe Latīnā"
