          "errāvēre iugīs. ferrō sonat altā bipennī",
          "fraxinus, ēvertunt actās ad sīdera pīnūs,",
          "rōbora nec cuneīs et olentem scindere cedrum",
          "nec plaustrīs cessant vectāre gementibus ornōs.",
          "Et iam Fāma volāns, tantī praenūntia lūctus,",
          "Evandrum Evandrīque domōs et moenia replet,",
