          "ōrdine flammārum et lātē discrīminat agrōs.",
          "contrā turbā Phrygum veniēns plangentia iungit",
          "agmina. quae postquam mātrēs succēdere tēctīs",
          "vīdērunt, maestam incendunt clāmōribus urbem.",
