          "haud ignārus eram quantum nova glōria in armīs",
          "et praedulce decus prīmō certāmine posset.",
          "prīmitiae iuvenis miserae bellīque propinquī",
          "dūra rudīmenta, et nūllī exaudīta deōrum",
          "vōta precēsque meae! tūque, ō sānctissima coniūnx,",
          "fēlīx morte tuā neque in hunc servāta dolōrem!",
          "contrā ego vīvendō vīcī mea fāta, superstēs",
          "restārem ut genitor. Trōum socia arma secūtum",
          "obruerent Rutulī tēlīs! animam ipse dedissem",
          "atque haec pompa domum mē, nōn Pallanta, referret!",
          "nec vōs arguerim, Teucrī, nec foedera nec quās",
