          "hīc pietāte prior. coeant in foedera dextrae,",
          "quā datur; ast armīs concurrant arma cavēte.\"",
          "et respōnsa simul quae sint, rēx optimē, rēgis",
          "audīstī et quae sit magnō sententia bellō.'",
